    async def test_bhv_sse_022_an_sse_event_named_error_raises_the_api_error_with_the_status_and_data_and_any_other_name_is_an_item(
        self,
    ) -> None:
        script = _Script(
            'event: update\ndata: fine\n\nevent: error\ndata: {"why":"bad"}\n\n',
            "data: again\n\n",
        )
        stream = await _sse(script, _fast())
        assert (await stream.__anext__()).event == "update"
        with pytest.raises(ApiException) as failure:
            await stream.__anext__()
        assert failure.value.status_code == 200
        assert failure.value.response_body == '{"why":"bad"}'
        assert len(script.last_ids) == 1, "an error event is not reconnected"
